     <div>
       <form @submit.prevent="submitPayment">
         <input type="email" v-model="paymentEmail" placeholder="Email" required />
         <input type="password" v-model="paymentPassword" placeholder="Password" required />
         <button type="submit">Pay Now</button>
       </form>
     </div>
   </template>

